//! Exact texture GLSL literal from Ship.java's static initializer.
pub(crate) const SOURCE: &str = "\n            #version 150 core\n\n            in vec2 vTexCoord;\n            out vec4 FragColor;\n            uniform usampler2D valueMask;\n\n            uniform sampler2D tex;\n            uniform sampler2D inlights;\n            uniform sampler2D exlights;\n            uniform sampler2D water;\n            uniform float day = 1.0;\n            uniform vec4 waterCol = vec4(0, 0.278431373, 0.623529411, 0.75);\n\n            const float pi = 3.141592;\n\n            void main() {\n                vec4 exlight = texture(exlights, vTexCoord);\n                vec3 brightness = clamp(vec3(smoothstep(-0.2, 0.8, day)) + exlight.rgb * exlight.a, 0.0, 1.0);\n                vec4 color = texture(tex, vTexCoord);\n                if ((texture(valueMask, vTexCoord).x & 2u) == 0u)\n                    color = mix(color, vec4(waterCol.rgb, 1.0), clamp(texture(water, vTexCoord).x, 0.0, 1.0) * 0.75);\n                color *= vec4(brightness, 1.0);\n                vec4 inlight = texture(inlights, vTexCoord);\n                color.rgb += inlight.rgb * inlight.a * (1.0-brightness);\n                FragColor = color;\n            }\n        ";
